    public enum Reminder: Codable, Hashable, Sendable {
        case before(minutes: Int)
        case at(date: DateKey, time: TimeOfDay)

        enum CodingKeys: String, CodingKey {
            case tag = "kind"
            case minutes = "minutes"
            case date = "date"
            case time = "time"
        }

        public init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            switch try container.decode(String.self, forKey: .tag) {
            case "before":
                let minutes = try container.decode(Int.self, forKey: .minutes)
                if decoder.validates {
                    do {
                        let value = minutes
                        try check(value >= 0, .minutes, in: container, "minutes at least 0")
                    }
                }
                self = .before(minutes: minutes)
            case "at":
                let date = try container.decode(DateKey.self, forKey: .date)
                let time = try container.decode(TimeOfDay.self, forKey: .time)
                if decoder.validates {
                    do {
                        let value = date
                        try check(value.range(of: #"^[0-9]{4}-[0-9]{2}-[0-9]{2}\z"#, options: .regularExpression) != nil, .date, in: container, "date matching ^\\d{4}-\\d{2}-\\d{2}$")
                    }
                    do {
                        let value = time
                        try check(value.range(of: #"^[0-9]{2}:[0-9]{2}\z"#, options: .regularExpression) != nil, .time, in: container, "time matching ^\\d{2}:\\d{2}$")
                    }
                }
                self = .at(date: date, time: time)
            case let tag:
                throw DecodingError.dataCorruptedError(forKey: .tag, in: container, debugDescription: "Unknown kind \(tag)")
            }
        }

        public func encode(to encoder: Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            switch self {
            case let .before(minutes):
                try container.encode("before", forKey: .tag)
                try container.encode(minutes, forKey: .minutes)
            case let .at(date, time):
                try container.encode("at", forKey: .tag)
                try container.encode(date, forKey: .date)
                try container.encode(time, forKey: .time)
            }
        }
    }

